import { notchChange } from '../ratings/notch.mjs';

/**
 * Indicator 12 (REQ-03-12): Watchlist level for a country rating change.
 *
 * Takes the analyst-confirmed previous and current country rating. An upgrade
 * or no change gives 0, a one-notch downgrade gives 1 and a downgrade of two
 * or more notches gives 2. These thresholds deliberately differ from the wl of
 * notchCalculator (Indicator 13).
 *
 * Invalid ratings are not handled here: the RangeError from notchChange
 * propagates unchanged.
 *
 * @param {string} previous previous country rating
 * @param {string} current current country rating
 * @returns {0 | 1 | 2} Watchlist level
 * @throws {RangeError} if either rating is not a valid scale value
 */
export function countryRatingChangeWl(previous, current) {
  const n = notchChange(previous, current);
  return n <= 0 ? 0 : n === 1 ? 1 : 2;
}
/**
 * Shared rating scale and notch calculator (REQ-06-02).
 * Pure functions: no I/O, no output, no imports.
 */

/**
 * Ordered rating scale, best first (index 0 = AAA, index 18 = CCC-).
 * Frozen: mutation attempts throw TypeError in strict mode.
 */
export const RATING_SCALE = Object.freeze([
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
]);

/**
 * Describe a rejected value for an error message. Never throws.
 * @param {unknown} value
 * @returns {string}
 */
function describeValue(value) {
  try {
    if (typeof value === 'string') return JSON.stringify(value);
    if (typeof value === 'symbol') return value.toString();
    if (typeof value === 'bigint') return `${value}n`;
    return Object.prototype.toString.call(value);
  } catch {
    return '[unprintable]';
  }
}

/**
 * Validate a rating and return its index in RATING_SCALE.
 * Non-strings are rejected before any string method or coercion.
 * Strings are trimmed (leading/trailing only) and upper-cased.
 * @param {unknown} value
 * @param {string} paramName
 * @returns {number}
 * @throws {RangeError}
 */
function toIndex(value, paramName) {
  if (typeof value === 'string') {
    const index = RATING_SCALE.indexOf(value.trim().toUpperCase());
    if (index !== -1) return index;
  }
  throw new RangeError(`Invalid rating for ${paramName}: ${describeValue(value)}`);
}

/**
 * Signed notch count between two ratings: index(current) - index(previous).
 * Positive = downgrade, negative = upgrade, 0 = unchanged.
 * @param {string} previous rating on RATING_SCALE (trimmed, case-insensitive)
 * @param {string} current rating on RATING_SCALE (trimmed, case-insensitive)
 * @returns {number} integer notch change
 * @throws {RangeError} if either argument is not a valid rating string
 */
export function notchChange(previous, current) {
  const from = toIndex(previous, 'previous');
  const to = toIndex(current, 'current');
  return to - from;
}

/**
 * Notch calculator (REQ-06-02) with the Indicator 13 thresholds:
 * WL 0 for <= 1 notch (incl. upgrade/unchanged), 1 for 2 notches, 2 for 3+.
 * @param {string} previous rating on RATING_SCALE
 * @param {string} current rating on RATING_SCALE
 * @returns {{notches: number, direction: 'downgrade'|'upgrade'|'unchanged', wl: 0|1|2}}
 * @throws {RangeError} if either argument is not a valid rating string
 */
export function notchCalculator(previous, current) {
  const notches = notchChange(previous, current);
  const direction = notches > 0 ? 'downgrade' : notches < 0 ? 'upgrade' : 'unchanged';
  const wl = notches <= 1 ? 0 : notches === 2 ? 1 : 2;
  return { notches, direction, wl };
}
