// T-02 QA: AC-15 purity, silence, dependency-free and test layout checks (criterion 8 a-d).
// Criterion 8(e) (full `node --test`) is a command run outside any test file.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { join } from 'node:path';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));

function walk(dir) {
  const out = [];
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) out.push(...walk(p));
    else out.push(p);
  }
  return out;
}

test('AC-15(a): no file under src/ uses console., process. or I/O module imports', () => {
  const files = walk(join(ROOT, 'src'));
  assert.ok(files.some((f) => f.endsWith(join('ratings', 'notch.mjs'))));
  assert.ok(files.some((f) => f.endsWith(join('indicators', 'countryRating.mjs'))));
